import itertools

def is_close(p1, p2):
    for a, b in zip(p1, p2):
        if abs(a - b) >= 2:
            return False
    return True

def find_max_n(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    adj = {p: [] for p in perms}
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            if is_close(perms[i], perms[j]):
                adj[perms[i]].append(perms[j])
                adj[perms[j]].append(perms[i])

    # Now we need to find the independence number of this graph.
    # Since the graph is small, we can use a simple recursive backtracking with pruning.
    max_indep = 0
    def backtrack(candidates, current_set):
        nonlocal max_indep
        if not candidates:
            max_indep = max(max_indep, len(current_set))
            return

        if len(current_set) + len(candidates) <= max_indep:
            return

        v = candidates[0]
        # Option 1: v is in the independent set
        new_candidates = [c for c in candidates[1:] if c not in adj[v]]
        backtrack(new_candidates, current_set + [v])

        # Option 2: v is not in the independent set
        backtrack(candidates[1:], current_set)

    backtrack(perms, [])
    return max_indep

print(f"n=2: {find_max_n(2)}")
print(f"n=3: {find_max_n(3)}")
print(f"n=4: {find_max_n(4)}")

import itertools
import networkx as nx

def is_close(p1, p2):
    for a, b in zip(p1, p2):
        if abs(a - b) >= 2:
            return False
    return True

def find_max_n_nx(n):
    perms = list(itertools.permutations(range(1, n + 1)))
    G = nx.Graph()
    G.add_nodes_from(range(len(perms)))
    for i in range(len(perms)):
        for j in range(i + 1, len(perms)):
            if is_close(perms[i], perms[j]):
                G.add_edge(i, j)

    # To find the maximum independent set, we find the maximum clique of the complement.
    complement_G = nx.complement(G)
    # For a small graph, we can use nx.clique.max_weight_clique or just iterate.
    # Actually, nx.clique.find_cliques generates all maximal cliques.
    max_clique_size = 0
    for clique in nx.find_cliques(complement_G):
        max_clique_size = max(max_clique_size, len(clique))
    return max_clique_size

print(f"n=5: {find_max_n_nx(5)}")

def is_prime(n):
    if n < 2: return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

print(is_prime(1597))
